-- Bible versions and the project freeze (spec 2026-10-28-channel-bible-design, section 4.5).
-- A channel's bible stops being a column and becomes append-only versions; each
-- project points at the version it started with. The keys are circular
-- (channels.current_bible_id <-> channel_bibles.channel_id), so the pointer
-- column stays nullable in SQL. On a fresh database every insert selects
-- nothing and the backfills touch no rows.

-- 1. The new table and the two new columns, nullable until they are filled.
CREATE TABLE "channel_bibles" (
	"id" text PRIMARY KEY NOT NULL,
	"channel_id" text NOT NULL,
	"version" integer NOT NULL,
	"bible" jsonb NOT NULL,
	"slot_ids" text[] NOT NULL,
	"complete" boolean NOT NULL,
	"note" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
ALTER TABLE "channels" ADD COLUMN "current_bible_id" text;
--> statement-breakpoint
ALTER TABLE "projects" ADD COLUMN "bible_id" text;
--> statement-breakpoint
-- 2. The first channel's version 1: the bible the prompts used to hard-code,
-- lifted verbatim. The literals must equal FIRST_CHANNEL_BIBLE and
-- EXAMPLE_SLOT_IDS (migration-0039.test.ts checks). If a later task corrects
-- an entry, it updates this literal in the same commit.
INSERT INTO "channel_bibles" ("id", "channel_id", "version", "bible", "slot_ids", "complete", "note")
SELECT '01BB0000000000000000000002', '01BB0000000000000000000001', 1,
	'{"subject":"corporate collapses, frauds, meltdowns and turnarounds","whatACaseIs":"A good case has: a documented paper trail (court filings, regulator actions, major-outlet reporting), a clear turn where the story changes, and consequences that can be shown rather than described. A bad case is one where the only sources are other YouTube videos, or where the interesting part is speculation about what someone was thinking.","subjectKind":"the company''s common name as Wikipedia titles it","audience":"adults who watch long-form money documentaries","narrationRegister":"plain, specific, unhurried","visualRegister":"the Netflix money documentary. Dark, patient, photographic realism. The people, in the rooms where it happened: principals at the table, in the corridor, at the podium, re-created with a reconstruction''s restraint. Empty rooms, documents and objects are punctuation between them, not the film.","titleStyle":"Sober, specific, curiosity-driven","ctaLine":"The full story is on the channel","caseCategories":[{"key":"collapse","label":"Collapse"},{"key":"con","label":"Con"},{"key":"meltdown","label":"Meltdown"},{"key":"turnaround","label":"Turnaround"},{"key":"empire","label":"Empire"}],"scriptRulesMd":"","directionRulesMd":"","subjectNoun":{"singular":"company","plural":"companies"},"voiceDos":[],"voiceDonts":[],"hedgingRules":"The hard rules:\n- Assert nothing the claim list does not support.\n- Where a claim is NOT adjudicated, write \"alleged\", \"reportedly\", \"according\n  to\" — never state it as established fact.\n- Never invent figures, dates, quotes or names.\n- Legal care is inline: \"alleged\", \"reportedly\", \"according to\". Never a\n  sentence of its own saying that nothing was proven, that no court has\n  found, or that this is an interpretation. The one exception is the film''s\n  single such sentence, where a chapter''s constraints ask for it.","examples":{"script-channel-subject":"corporate collapses, frauds and meltdowns","script-elegant-variation":"\"the\n  payments giant\", \"the embattled firm\", \"the Munich-based company\"","script-storyline-examples":"the money, the credit, the courts","script-subject-with-article":"a company","script-close-hedge":"hedged where the law needs it","script-opening-collapse":"the size of the collapse","script-concrete-figure":"\"Thirty thousand\n  pensions\", never \"significant sums\"","script-implicit-question":"\"The auditors signed. The money was not there.\"","script-foreshadow":"\"That signature would be the\n  last one EY ever gave them\"","script-middle-turn":"the stakes reaching people who are not\n  investors","script-legal-care":"Legal care is carried by the inline hedges: reportedly, according to,\n  alleged. Never narrate the caveat as a sentence of its own: no \"no court\n  has found\", no \"that is an interpretation\", no \"the record shows the order\n  of events and nothing more\". Once in the whole film, where a listener would\n  otherwise infer guilt, the outline''s constraints may ask for one plain\n  sentence that nothing has been proven","dossier-channel-subject":"corporate collapses, frauds and comebacks","dossier-wanted-example":"to make every quarter look like\n  growth","dossier-scene-examples":"A results call, a stage keynote, a board meeting, a raid,\n  a resignation, a short seller''s report landing","dossier-claims-focus":"what the money did, who said what, what the numbers show over time","direction-abstract-example":"\"Financial pressure on the business and disagreements inside\n  the boardroom\" is the principals at the boardroom table, mid-argument","direction-subject-marks":"A real company''s own marks belong in frame when the film is about that\n  company: the sign above the door, the badge on a laptop lid, the lanyard\n  on the desk. Name the company and let the shot hold what is really\n  there.","direction-background-people":"investors","direction-identity-example":"Emad Mostaque, founder of\n  Stability AI","direction-worked-example":"\"Emad Mostaque, founder of Stability AI, sitting at a desk\" is right; adding \"male in his 40s, short dark hair, closely cropped beard\"","direction-never-acts":"no\n  cash changing hands, no shredder, no handcuffs, no whispered deal","direction-guardrail-rule":"never handling cash or signing an invented contract; never in\n  handcuffs; never mocked\"). It never fences a person away from ordinary\n  settings such as desks, documents, boardrooms or meetings. The guardrail\n  governs what the planner writes; it is never pasted into the image\n  prompt. Image models read negation as suggestion, so \"never in\n  handcuffs\" in a prompt invites handcuffs. Its concrete nouns may become\n  the negative prompt (\"no gavel, no handcuffs, no cash","direction-preflight-settings":"a desk, a\n  document, a boardroom or a meeting","direction-premise":"a corporate collapse","direction-motif-generic":"any corporate collapse","direction-never-show-examples":"fabricated documents\n  presented as real filings, generated images passed off as real\n  photographs, a figure sourced to a filing that does not exist, an invented\n  crime","direction-guardrail-book":"specific acts the claims do not establish (handling cash, signing an\n  invented contract, handcuffs), plus caricature, malice, humiliation. It\n  never keeps them away from desks, documents, boardrooms, meetings,\n  interviews or podiums","shotlist-two-units":"a valuation in billions against a\nmargin in percent","shotlist-headline-cue":"\"the Financial Times reported\", \"the paper found\", \"when the story broke\"","shotlist-guardrail-negation":"\"never in handcuffs\" as a request for handcuffs","shotlist-map-route-example":"money flows, HQ hops","direction-default-guardrail":"never handling cash or signing an invented contract; never in handcuffs","direction-cast-settings":"desks, documents, boardrooms or\n  meetings","graphics-worked-beat":"Example 1, a text-only beat. The slot is 7.5 s; its words are \"The\" 0.0 s, \"auditors\"\n0.3 s, \"could\" 0.9 s, \"not\" 1.2 s, \"find\" 1.5 s, \"1.9\" 2.6 s, \"billion\" 3.0 s, \"euros.\"\n3.4 s, \"It\" 4.4 s, \"had\" 4.6 s, \"never\" 5.0 s, \"existed.\" 5.4 s. Claim 2 reads \"Wirecard\nreported €1.9 billion in trustee accounts that auditors could not confirm existed.\" The\nanswer is {\"title\": \"The missing €1.9bn\", \"facts\": [{\"text\": \"€1.9bn\", \"claim\": 2}],\n\"source\": this component as a JSON string}:\n\n// Kinetic type: the line builds word by word as it is spoken, the figure\n// springs in on \"1.9 billion\" with the hero preset (one small overshoot, once\n// in the beat), \"never existed\" strikes it through, and the finished frame\n// holds to the end.\n// Every length and every curve is a token; positions follow the narration.\nconst LINE_UNTIL_MS = 2400\nconst FIGURE_AT_MS = 2600\nconst CLOSING_AT_MS = 4400\nconst STRIKE_AT_MS = 5000\n\n// A helper, called directly: an arrival, 0 to 1 over motion.ms.enter from atMs, held at 1.\nfunction arrive(frame, fps, atMs) {\n  return Remotion.interpolate(\n    frame, [motion.frames(atMs, fps), motion.frames(atMs + motion.ms.enter, fps)], [0, 1],\n    { easing: motion.ease.enter, extrapolateLeft: ''clamp'', extrapolateRight: ''clamp'' },\n  )\n}\n\n// A helper, called directly: one word of the line, rising in as it is spoken.\nfunction wordSpan(word, frame, fps, unit) {\n  const enter = arrive(frame, fps, word.atMs)\n  const rise = ''translateY('' + (1 - enter) * motion.px.rise * unit + ''px)''\n  return (\n    <span\n      key={word.atMs}\n      style={{ display: ''inline-block'', marginRight: ''0.25em'', opacity: enter, transform: rise }}\n    >\n      {word.text}\n    </span>\n  )\n}\n\nfunction Graphic(props) {\n  const frame = Remotion.useCurrentFrame()\n  const { width, height, fps } = Remotion.useVideoConfig()\n  const { colors, fonts } = props.brand\n  const inset = props.safeArea\n  const portrait = height > width\n  const unit = Math.min(width, height) / 1080\n\n  // The words said before the figure, each entering as it is spoken.\n  const line = props.words.filter((word) => word.atMs < LINE_UNTIL_MS)\n  // The hero figure: the one spring of the beat. It rises into place and scales up from\n  // motion.scale.enter; the hero preset''s one overshoot shows on the rise, a few pixels\n  // past the mark and back, not on the scale, where it would not be seen.\n  // It rises twice motion.px.rise, so the overshoot has room to read; a plain fade keeps the single rise.\n  const pop = Remotion.spring({\n    frame, fps, delay: motion.frames(FIGURE_AT_MS, fps), config: motion.spring.hero,\n  })\n  const closing = arrive(frame, fps, CLOSING_AT_MS)\n  // The strike is the figure''s payoff, so it takes the emphasis curve.\n  // It draws across over motion.ms.draw.\n  const strike = Remotion.interpolate(\n    frame, [motion.frames(STRIKE_AT_MS, fps), motion.frames(STRIKE_AT_MS + motion.ms.draw, fps)], [0, 1],\n    { easing: motion.ease.emphasis, extrapolateLeft: ''clamp'', extrapolateRight: ''clamp'' },\n  )\n\n  return (\n    <Remotion.AbsoluteFill\n      style={{\n        paddingTop: inset.top, paddingRight: inset.right,\n        paddingBottom: inset.bottom, paddingLeft: inset.left,\n        justifyContent: ''center'', gap: 28 * unit,\n        alignItems: portrait ? ''center'' : ''flex-start'', textAlign: portrait ? ''center'' : ''left'',\n      }}\n    >\n      <div\n        style={{\n          fontFamily: fonts.heading, fontSize: 72 * unit, lineHeight: 1.15,\n          color: colors.textPrimary, maxWidth: portrait ? ''100%'' : ''70%'',\n        }}\n      >\n        {line.map((word) => wordSpan(word, frame, fps, unit))}\n      </div>\n      <div\n        style={{\n          position: ''relative'', fontFamily: fonts.numbers, fontSize: 220 * unit, lineHeight: 1,\n          color: colors.accent, opacity: Math.min(1, pop),\n          transform: ''translateY('' + (1 - pop) * 2 * motion.px.rise * unit + ''px) scale(''\n            + (motion.scale.enter + (1 - motion.scale.enter) * pop) + '')'',\n          transformOrigin: portrait ? ''center'' : ''left center'',\n        }}\n      >\n        €1.9bn\n        <div\n          style={{\n            position: ''absolute'', left: 0, top: ''52%'', height: 14 * unit,\n            width: strike * 100 + ''%'', backgroundColor: colors.semantic.collapse,\n          }}\n        />\n      </div>\n      <div\n        style={{\n          fontFamily: fonts.title, fontSize: 56 * unit, color: colors.semantic.collapse,\n          opacity: closing, transform: ''translateY('' + (1 - closing) * motion.px.rise * unit + ''px)'',\n        }}\n      >\n        It had never existed.\n      </div>\n    </Remotion.AbsoluteFill>\n  )\n}","graphics-worked-chart":"Example 2, a chart slot. The slot is 7.2 s; \"2016\" is said at 1.0 s, \"2017\" at 2.0 s,\n\"2018\" at 3.0 s and \"2019\" at 4.2 s. Its data is\n{\"series\":[{\"label\":\"Trustee cash reported\",\"unit\":\"€bn\",\"points\":[{\"x\":\"2016\",\"y\":0.3},{\"x\":\"2017\",\"y\":0.6},{\"x\":\"2018\",\"y\":1.1},{\"x\":\"2019\",\"y\":1.9}]}],\"takeaway\":\"The cash grew every year\",\"annotations\":[{\"atX\":\"2019\",\"text\":\"Never found\"}]}\nClaims 5 to 8 hold the four years'' figures. The answer is {\"title\": \"Trustee cash, year\nby year\", \"facts\": [{\"text\": \"2019\", \"claim\": 8}, {\"text\": \"1.9\", \"claim\": 8}], \"source\":\nthis component as a JSON string}. The facts cite the point the story lands on; the other\npoints'' digits come off props.data and need no entry:\n\n// A chart from props.data: the title and its subtitle stagger in, one bar\n// per point draws on as its year is spoken, the annotation lands on its bar\n// after the last one has grown, and the finished chart holds to the end.\n// Every length and every curve is a token; positions follow the narration.\n\n// When the narration names a point: the first word that starts with its label.\nfunction spokenAt(point, index, words) {\n  const said = words.find((word) => word.text.indexOf(point.x) === 0)\n  return said ? said.atMs : motion.ms.enter + index * (motion.ms.draw + motion.ms.gap)\n}\n\n// A helper, called directly: 0 to 1 over lengthMs from atMs on the arrival curve, held at 1.\nfunction arrive(frame, fps, atMs, lengthMs) {\n  return Remotion.interpolate(\n    frame, [motion.frames(atMs, fps), motion.frames(atMs + lengthMs, fps)], [0, 1],\n    { easing: motion.ease.enter, extrapolateLeft: ''clamp'', extrapolateRight: ''clamp'' },\n  )\n}\n\n// A helper, called directly: one bar with its value and, on the last, its note.\nfunction bar(frame, fps, spec) {\n  const { colors, fonts } = spec.brand\n  const unit = spec.unit\n  const grow = arrive(frame, fps, spec.atMs, motion.ms.draw)\n  const noted = arrive(frame, fps, spec.noteAtMs, motion.ms.enter)\n  const column = { flex: 1, display: ''flex'', flexDirection: ''column'', alignItems: ''center'' }\n  return (\n    <div key={spec.point.x} style={{ ...column, justifyContent: ''flex-end'' }}>\n      {spec.note ? (\n        <div\n          style={{\n            fontFamily: fonts.title, fontSize: 34 * unit, marginBottom: 10 * unit,\n            color: colors.semantic.collapse, opacity: noted,\n            transform: ''translateY('' + (1 - noted) * motion.px.rise * unit + ''px)'',\n          }}\n        >\n          {spec.note}\n        </div>\n      ) : null}\n      <div\n        style={{\n          fontFamily: fonts.numbers, fontSize: 40 * unit, marginBottom: 10 * unit,\n          color: spec.color, opacity: grow,\n        }}\n      >\n        {String(spec.point.y)}\n      </div>\n      <div\n        style={{\n          width: ''60%'', height: spec.share * grow * spec.plot,\n          borderRadius: 6 * unit, backgroundColor: spec.color,\n        }}\n      />\n      <div style={{ fontFamily: fonts.body, fontSize: 30 * unit, color: colors.textSecondary }}>\n        {spec.point.x}\n      </div>\n    </div>\n  )\n}\n\nfunction Graphic(props) {\n  const frame = Remotion.useCurrentFrame()\n  const { width, height, fps } = Remotion.useVideoConfig()\n  const { colors, fonts } = props.brand\n  const inset = props.safeArea\n  const portrait = height > width\n  const unit = Math.min(width, height) / 1080\n  const series = props.data.series[0]\n  const top = Math.max(...series.points.map((point) => point.y))\n  const lands = series.points.map((point, index) => spokenAt(point, index, props.words))\n  const last = series.points.length - 1\n  const note = (props.data.annotations || [])[0]\n  // The title arrives first and the subtitle one stagger step after it: motion.order (title, then body), shown on a pair.\n  const titleIn = arrive(frame, fps, 0, motion.ms.enter)\n  const subtitleIn = arrive(frame - motion.stagger(1, fps), fps, 0, motion.ms.enter)\n  const align = portrait ? ''center'' : ''left''\n\n  return (\n    <Remotion.AbsoluteFill\n      style={{\n        paddingTop: inset.top, paddingRight: inset.right,\n        paddingBottom: inset.bottom, paddingLeft: inset.left,\n        justifyContent: ''center'', gap: 24 * unit,\n      }}\n    >\n      <div\n        style={{\n          fontFamily: fonts.heading, fontSize: 60 * unit, lineHeight: 1.1,\n          color: colors.textPrimary, opacity: titleIn, textAlign: align,\n        }}\n      >\n        {props.data.takeaway}\n      </div>\n      <div\n        style={{\n          fontFamily: fonts.body, fontSize: 28 * unit, color: colors.textSecondary,\n          opacity: subtitleIn, textAlign: align,\n        }}\n      >\n        {series.label + '', '' + series.unit}\n      </div>\n      <div style={{ display: ''flex'', alignItems: ''flex-end'', gap: 16 * unit }}>\n        {series.points.map((point, index) =>\n          bar(frame, fps, {\n            brand: props.brand, unit: unit, point: point,\n            share: point.y / top, plot: (portrait ? 0.32 : 0.34) * height, atMs: lands[index],\n            color: index === last ? colors.accent : Remotion.withAlpha(colors.textSecondary, 0.55),\n            note: note && note.atX === point.x ? note.text : null,\n            noteAtMs: lands[last] + motion.ms.draw + motion.ms.gap,\n          }),\n        )}\n      </div>\n    </Remotion.AbsoluteFill>\n  )\n}","metadata-channel-subject":"corporate collapses, cons and meltdowns","metadata-title-mechanisms":"a question, a number, a timeline\n  (\"Nine days\"), a contradiction, a consequence","metadata-description-opening":"the company, its\n  best-known product and what happened","metadata-tag-kinds":"the\n  company, the product, the people, the events, the topic","digest-channel-subject":"corporate collapses","script-read-aloud-numbers":"\"1.9 billion euros\", not \"€1.9B\"; \"the S and P 500\" is wrong, \"the S&P 500\"\n  is read correctly","script-hedge-kind":"legal hedges","direction-era-objects":"CRT monitors, a fax machine, a flip phone, paper ledgers","direction-emotion-body":"\"a\n  worried executive\"; \"an executive, jaw set, both hands flat on the\n  desk\"","direction-recreated-scenes":"a principal at a desk with\n  papers, in a boardroom, in a corridor, at a podium, in a car, in an\n  interview, reading a phone","dossier-status-subject":"the people and the money"},"hooks":[],"openings":[],"titles":[],"language":"en","country":"US","keywordContext":"documentary","channelTags":[],"disclaimer":"This video is documentary commentary for education. It is not financial advice. Narration is AI-generated. Some visuals are AI re-creations for illustration, including likenesses of real people; they are not photographs of real events. Sources are listed above.","youtubeCategoryId":null,"auditionLine":"In June 2020, Wirecard admitted that roughly two billion euros of cash on its balance sheet probably did not exist. The auditors had signed the accounts for years."}'::jsonb,
	ARRAY['script-channel-subject', 'script-elegant-variation', 'script-storyline-examples', 'script-subject-with-article', 'script-close-hedge', 'script-opening-collapse', 'script-concrete-figure', 'script-implicit-question', 'script-foreshadow', 'script-middle-turn', 'script-legal-care', 'dossier-channel-subject', 'dossier-wanted-example', 'dossier-scene-examples', 'dossier-claims-focus', 'direction-abstract-example', 'direction-subject-marks', 'direction-background-people', 'direction-identity-example', 'direction-worked-example', 'direction-never-acts', 'direction-guardrail-rule', 'direction-preflight-settings', 'direction-premise', 'direction-motif-generic', 'direction-never-show-examples', 'direction-guardrail-book', 'shotlist-two-units', 'shotlist-headline-cue', 'shotlist-guardrail-negation', 'shotlist-map-route-example', 'direction-default-guardrail', 'direction-cast-settings', 'graphics-worked-beat', 'graphics-worked-chart', 'metadata-channel-subject', 'metadata-title-mechanisms', 'metadata-description-opening', 'metadata-tag-kinds', 'digest-channel-subject', 'script-read-aloud-numbers', 'script-hedge-kind', 'direction-era-objects', 'direction-emotion-body', 'direction-recreated-scenes', 'dossier-status-subject']::text[],
	true, 'Lifted from code'
WHERE EXISTS (SELECT 1 FROM "channels" WHERE "id" = '01BB0000000000000000000001');
