ALTER TABLE "channel_bibles" ADD CONSTRAINT "channel_bibles_channel_id_channels_id_fk" FOREIGN KEY ("channel_id") REFERENCES "public"."channels"("id") ON DELETE restrict ON UPDATE no action;
--> statement-breakpoint
CREATE UNIQUE INDEX "channel_bibles_channel_version_key" ON "channel_bibles" USING btree ("channel_id","version");
--> statement-breakpoint
ALTER TABLE "channels" ADD CONSTRAINT "channels_current_bible_id_channel_bibles_id_fk" FOREIGN KEY ("current_bible_id") REFERENCES "public"."channel_bibles"("id") ON DELETE no action ON UPDATE no action;
--> statement-breakpoint
ALTER TABLE "projects" ADD CONSTRAINT "projects_bible_id_channel_bibles_id_fk" FOREIGN KEY ("bible_id") REFERENCES "public"."channel_bibles"("id") ON DELETE restrict ON UPDATE no action;
